/**
 * 결함 데이터 처리
 */
scwin.processDefData = function(allData, totalCount) {
    console.log("결함 데이터 처리 시작:", allData.length, "건");

    // 권한에 따른 데이터 필터링
    var filteredData = scwin.filterDataByPermission(allData || []);

    // 상태별 데이터 필터링
    var newData = [];
    var processingData = [];
    var completedData = [];

    for (var i = 0; i < filteredData.length; i++) {
        var item = filteredData[i];

        // 우선순위명, 상태명 추가
        item.priorityName = scwin.getPriorityName(item.priority);
        item.statusName = scwin.getStatusName(item.status);

        // 테스트케이스명이 없으면 기본값 설정
        if (!item.testName || item.testName === "") {
            item.testName = "테스트케이스 미지정";
        }

        // 상태별 분류
        if (item.status === "NEW") {
            newData.push(item);
        } else if (item.status === "IPR") {
            processingData.push(item);
        } else if (item.status === "COM" || item.status === "FIX") {
            completedData.push(item);
        }
    }

    // 상태별 데이터 저장
    try {
        scwin.newPageInfo.data = newData;
        scwin.newPageInfo.totalCount = newData.length;
        scwin.processingPageInfo.data = processingData;
        scwin.processingPageInfo.totalCount = processingData.length;
        scwin.completedPageInfo.data = completedData;
        scwin.completedPageInfo.totalCount = completedData.length;
    } catch (e) {
        console.error("상태별 페이징 정보 설정 실패:", e);
        scwin.initializeData();
        scwin.newPageInfo.data = newData;
        scwin.newPageInfo.totalCount = newData.length;
        scwin.processingPageInfo.data = processingData;
        scwin.processingPageInfo.totalCount = processingData.length;
        scwin.completedPageInfo.data = completedData;
        scwin.completedPageInfo.totalCount = completedData.length;
    }

    // 그리드 데이터 업데이트
    scwin.updateGridData();

    // 카운트 업데이트
    scwin.updateCountLabels(filteredData.length, newData.length, processingData.length, completedData.length);

    // 페이징 업데이트
    scwin.updatePagination();

    // 우선순위 스타일 적용
    setTimeout(function() {
        scwin.setPriorityStyle();
    }, 100);

    console.log("결함 데이터 처리 완료");
};

/**
 * 데이터 필터링 (권한 적용)
 */
scwin.filterDataByPermission = function(data) {
    if (!data || data.length === 0) {
        return data;
    }

    // PM인 경우 모든 데이터 반환
    if (scwin.isPM()) {
        console.log("PM 권한: 전체 데이터 표시");
        return data;
    }

    // 일반 사용자인 경우 자신이 담당한 결함만 필터링
    var filteredData = data.filter(function(item) {
        return item.assignee === scwin.CURRENT_USER_ID;
    });

    console.log("일반 사용자 권한: 필터링된 데이터", {
        전체: data.length,
        필터링후: filteredData.length,
        담당자: scwin.CURRENT_USER_ID
    });

    return filteredData;
};

/**
 * 그리드 데이터 업데이트
 */
scwin.updateGridData = function() {
    console.log("그리드 데이터 업데이트 시작");

    try {
        if (!scwin.newPageInfo || !scwin.processingPageInfo || !scwin.completedPageInfo) {
            console.warn("페이징 객체가 존재하지 않습니다. 초기화를 실행합니다.");
            scwin.initializeData();
        }

        var newPageData = scwin.getPageData(scwin.newPageInfo.data, scwin.newPageInfo);
        dlt_newList.setJSON(newPageData);

        var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
        dlt_processingList.setJSON(processingPageData);

        var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
        dlt_completedList.setJSON(completedPageData);

        console.log("그리드 데이터 업데이트 완료");
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
        dlt_newList.setJSON([]);
        dlt_processingList.setJSON([]);
        dlt_completedList.setJSON([]);
    }
};

/**
 * 페이지별 데이터 추출
 */
scwin.getPageData = function(data, pageInfo) {
    if (!data || !pageInfo || !Array.isArray(data)) {
        console.warn("getPageData: 잘못된 데이터 또는 페이징 정보");
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;

    if (startIndex < 0) startIndex = 0;
    if (endIndex > data.length) endIndex = data.length;

    return data.slice(startIndex, endIndex);
};

/**
 * 카운트 라벨 업데이트
 */
scwin.updateCountLabels = function(total, newCount, processingCount, completedCount) {
    try {
        spn_newListCnt.setLabel(newCount);
        spn_processingListCnt.setLabel(processingCount);
        spn_completedListCnt.setLabel(completedCount);
    } catch (e) {
        console.error("카운트 라벨 업데이트 오류:", e);
    }
};

/**
 * 페이징 업데이트
 */
scwin.updatePagination = function() {
    try {
        scwin.updateStatePagination(scwin.newPageInfo, pgl_new);
        scwin.updateStatePagination(scwin.processingPageInfo, pgl_processing);
        scwin.updateStatePagination(scwin.completedPageInfo, pgl_completed);
    } catch (e) {
        console.error("페이징 업데이트 오류:", e);
    }
};

/**
 * 상태별 페이징 업데이트
 */
scwin.updateStatePagination = function(pageInfo, paginationComponent) {
    try {
        if (!pageInfo || !paginationComponent) {
            console.warn("updateStatePagination: 잘못된 파라미터");
            return;
        }

        var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);

        if (totalPages > 0) {
            paginationComponent.setCount(totalPages);
            paginationComponent.setSelectedIndex(pageInfo.currentPage);
        } else {
            paginationComponent.setCount(0);
        }
    } catch (e) {
        console.error("상태별 페이징 업데이트 오류:", e);
    }
};

/**
 * 우선순위별 배지 스타일 적용
 */
scwin.setPriorityStyle = function () {
    console.log("우선순위 배지 스타일 적용 시작");

    try {
        // 신규 그리드
        const newRowCount = dlt_newList.getTotalRow();
        const newColIndex = new_grd.getColumnIndex("priorityName");

        for (let i = 0; i < newRowCount; i++) {
            const priority = dlt_newList.getCellData(i, "priority");
            const priorityStyles = scwin.getPriorityStyleConfig(priority);

            const styles = [
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "background-color", styleValue: priorityStyles.backgroundColor },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "color", styleValue: priorityStyles.textColor },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "border-radius", styleValue: "12px" },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "text-align", styleValue: "center" },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "font-weight", styleValue: "bold" },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "font-size", styleValue: "11px" },
                { type: "cell", rowIndex: i, colIndex: newColIndex, styleName: "border", styleValue: "1px solid " + priorityStyles.borderColor }
            ];

            styles.forEach(style => new_grd.setStyleAll(style));
        }

        // 진행중 그리드
        const processingRowCount = dlt_processingList.getTotalRow();
        const processingColIndex = processing_grd.getColumnIndex("priorityName");

        for (let i = 0; i < processingRowCount; i++) {
            const priority = dlt_processingList.getCellData(i, "priority");
            const priorityStyles = scwin.getPriorityStyleConfig(priority);

            const styles = [
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "background-color", styleValue: priorityStyles.backgroundColor },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "color", styleValue: priorityStyles.textColor },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "border-radius", styleValue: "12px" },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "text-align", styleValue: "center" },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "font-weight", styleValue: "bold" },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "font-size", styleValue: "11px" },
                { type: "cell", rowIndex: i, colIndex: processingColIndex, styleName: "border", styleValue: "1px solid " + priorityStyles.borderColor }
            ];

            styles.forEach(style => processing_grd.setStyleAll(style));
        }

        // 완료 그리드
        const completedRowCount = dlt_completedList.getTotalRow();
        const completedColIndex = completed_grd.getColumnIndex("priorityName");

        for (let i = 0; i < completedRowCount; i++) {
            const priority = dlt_completedList.getCellData(i, "priority");
            const priorityStyles = scwin.getPriorityStyleConfig(priority);

            const styles = [
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "background-color", styleValue: priorityStyles.backgroundColor },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "color", styleValue: priorityStyles.textColor },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "border-radius", styleValue: "12px" },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "text-align", styleValue: "center" },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "font-weight", styleValue: "bold" },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "font-size", styleValue: "11px" },
                { type: "cell", rowIndex: i, colIndex: completedColIndex, styleName: "border", styleValue: "1px solid " + priorityStyles.borderColor }
            ];

            styles.forEach(style => completed_grd.setStyleAll(style));
        }

        console.log("우선순위 배지 스타일 적용 완료");

    } catch (e) {
        console.error("우선순위 스타일 적용 오류:", e);
    }
};

/**
 * 우선순위별 스타일 설정
 */
scwin.getPriorityStyleConfig = function(priority) {
    let backgroundColor = "#f8f9fa";
    let textColor = "#333333";
    let borderColor = "#dee2e6";

    switch (priority) {
        case "CR": // 긴급
            backgroundColor = "#ffe6e6";
            textColor = "#dc3545";
            borderColor = "#f5c6cb";
            break;
        case "HI": // 높음
            backgroundColor = "#fff3cd";
            textColor = "#856404";
            borderColor = "#ffeaa7";
            break;
        case "MD": // 보통
            backgroundColor = "#d1ecf1";
            textColor = "#0c5460";
            borderColor = "#bee5eb";
            break;
        case "LO": // 낮음
            backgroundColor = "#d4edda";
            textColor = "#155724";
            borderColor = "#c3e6cb";
            break;
    }

    return { backgroundColor, textColor, borderColor };
};

/**
 * 우선순위명 변환
 */
scwin.getPriorityName = function(priority) {
    switch(priority) {
        case "CR": return "긴급";
        case "HI": return "높음";
        case "MD": return "보통";
        case "LO": return "낮음";
        default: return priority;
    }
};

/**
 * 상태명 변환
 */
scwin.getStatusName = function(status) {
    switch(status) {
        case "NEW": return "신규";
        case "IPR": return "진행중";
        case "FIX": return "해결";
        case "REO": return "재오픈";
        case "COM": return "완료";
        default: return status;
    }
};

/**
