 */
scwin.new_grd_oncelldblclick = function(row, col, colId) {
    console.log("신규 그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_newList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
