/**
 * 결함 상세 팝업 열기 (최종 버전)
 */
scwin.openDefectDetailPopup = function(selectedData) {
    console.log("결함 상세 팝업 열기 (최종 버전):", selectedData);

    if (!selectedData || !selectedData.id) {
        $c.win.alert("유효하지 않은 데이터입니다.");
        return;
    }

    // 전체 데이터에서 해당 ID의 완전한 데이터 찾기
    var fullData = scwin.findFullDefectData(selectedData.id);

    if (fullData) {
        console.log("완전한 데이터 발견:", fullData);
        console.log("description 필드:", fullData.description ? "있음 (" + fullData.description.length + "자)" : "없음");
        console.log("remarks 필드:", fullData.remarks ? "있음 (" + fullData.remarks.length + "자)" : "없음");

        scwin.openDefectPopupWithDetailData(fullData);
    } else {
        console.log("완전한 데이터를 찾을 수 없음, 기본 데이터로 팝업 열기");
        scwin.openDefectPopupWithDetailData(selectedData);
    }
};

