/**
 * 검색 조건 초기화 버튼 (수정된 버전)
 */
scwin.btn_searchReset_onclick = function(e) {
    console.log("검색 조건 초기화 버튼 클릭");

    // 완전 초기화
    scwin.resetAllSearchConditions();

    // 초기화 후 검색 실행
    setTimeout(function() {
        scwin.btn_search_onclick();
    }, 100);
};
/**
 * 탭 활성화 시 호출되는 함수 (새로 추가)
 */
scwin.onTabActivated = function() {
    console.log("결함 탭 활성화됨");

    // 단위테스트에서 온 파라미터가 없다면 검색 조건 초기화
    try {
        var unitTestData = $p.getParameter("tabData");
        if (!unitTestData || !unitTestData.fromUnitTest) {
            console.log("일반 탭 활성화 - 검색 조건 초기화");
            scwin.resetAllSearchConditions();

            // 초기화 후 검색
            setTimeout(function() {
                scwin.btn_search_onclick();
            }, 100);
        }
    } catch (e) {
        console.log("탭 활성화 처리 중 오류:", e);
    }
};

/**
 * 페이지 새로고침/재진입 감지 (새로 추가)
 */
scwin.checkPageRefresh = function() {
    // sessionStorage를 사용해서 페이지 재진입 감지
    try {
        var lastTestId = sessionStorage.getItem("lastDefectTestId");
        var currentTestId = dmp_search.get("testId");

        // 이전에 설정된 testId와 현재 testId가 다르면 초기화
        if (lastTestId && lastTestId !== currentTestId) {
            console.log("이전 testId와 다름 - 초기화:", lastTestId, "→", currentTestId);
            scwin.resetAllSearchConditions();
        }

        // 현재 testId 저장
        if (currentTestId) {
            sessionStorage.setItem("lastDefectTestId", currentTestId);
        } else {
            sessionStorage.removeItem("lastDefectTestId");
        }

    } catch (e) {
        console.log("페이지 새로고침 감지 실패:", e);
    }
};

// onpageload에서 페이지 새로고침 체크 추가
scwin.originalOnpageload = scwin.onpageload;
scwin.onpageload = function() {
    // 페이지 새로고침 체크
    scwin.checkPageRefresh();

    // 기존 onpageload 실행
    scwin.originalOnpageload();
};

/**
 * 엑셀 다운로드
 */
scwin.btn_excel_download_onclick = function(e) {
    var newData = scwin.newPageInfo.data || [];
    var processingData = scwin.processingPageInfo.data || [];
    var completedData = scwin.completedPageInfo.data || [];

    var totalCount = newData.length + processingData.length + completedData.length;

    if (totalCount === 0) {
        $c.win.alert("다운로드할 결함이 없습니다.");
        return;
    }

    console.log("전체 결함 통합 엑셀 다운로드:", totalCount, "건");

    // 모든 데이터를 합쳐서 상태별로 정렬
    var allData = [];

    // 신규 데이터 추가
    newData.forEach(function(item) {
        allData.push({
            id: item.id || '',
            testId: item.testId || '',
            testName: item.testName || '',
            name: item.name || '',
            description: item.description || '',
            priority: item.priority || '',
            priorityName: item.priorityName || scwin.getPriorityName(item.priority) || '',
            status: item.status || 'NEW',
            statusName: '신규',
            assignee: item.assignee || '',
            assigneeName: item.assigneeName || '',
            fixDueDate: item.fixDueDate || '',
            fixedDate: item.fixedDate || '',
            responsePlan: item.responsePlan || '',
            createdAt: item.createdAt || '',
            updatedAt: item.updatedAt || '',
            createdBy: item.createdBy || '',
            updatedBy: item.updatedBy || '',
            statusOrder: 1
        });
    });

    // 진행중 데이터 추가
    processingData.forEach(function(item) {
        allData.push({
            id: item.id || '',
            testId: item.testId || '',
            testName: item.testName || '',
            name: item.name || '',
            description: item.description || '',
            priority: item.priority || '',
            priorityName: item.priorityName || scwin.getPriorityName(item.priority) || '',
            status: item.status || 'IPR',
            statusName: '진행중',
            assignee: item.assignee || '',
            assigneeName: item.assigneeName || '',
            fixDueDate: item.fixDueDate || '',
            fixedDate: item.fixedDate || '',
            responsePlan: item.responsePlan || '',
            createdAt: item.createdAt || '',
            updatedAt: item.updatedAt || '',
            createdBy: item.createdBy || '',
            updatedBy: item.updatedBy || '',
            statusOrder: 2
        });
    });

    // 완료 데이터 추가
    completedData.forEach(function(item) {
        allData.push({
            id: item.id || '',
            testId: item.testId || '',
            testName: item.testName || '',
            name: item.name || '',
            description: item.description || '',
            priority: item.priority || '',
            priorityName: item.priorityName || scwin.getPriorityName(item.priority) || '',
            status: item.status || 'COM',
            statusName: '완료',
            assignee: item.assignee || '',
            assigneeName: item.assigneeName || '',
            fixDueDate: item.fixDueDate || '',
            fixedDate: item.fixedDate || '',
            responsePlan: item.responsePlan || '',
            createdAt: item.createdAt || '',
            updatedAt: item.updatedAt || '',
            createdBy: item.createdBy || '',
            updatedBy: item.updatedBy || '',
            statusOrder: 3
        });
    });

    // 상태별로 정렬
    allData.sort(function(a, b) {
        return a.statusOrder - b.statusOrder;
    });

    // 원본 데이터 백업
    var originalData = dlt_newList.getAllJSON();

    // 통합 데이터로 그리드 설정
    dlt_newList.setJSON(allData);

    var options = {
        fileName: "결함_전체목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1,
        trim: 1,
        processMsg: "전체 결함 엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function() {
            dlt_newList.setJSON(originalData);
            $c.win.alert("전체 결함 엑셀 파일 다운로드가 완료되었습니다. (총 " + totalCount + "건)");
        },
        onFailureCallback: function() {
            dlt_newList.setJSON(originalData);
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
        }
    };

    try {
        new_grd.advancedExcelDownload(options);
    } catch (error) {
        console.error("advancedExcelDownload 오류:", error);
        try {
            new_grd.excelDownload("결함_전체목록_" + new Date().toISOString().slice(0, 10));
            dlt_newList.setJSON(originalData);
            $c.win.alert("엑셀 다운로드가 완료되었습니다. (총 " + totalCount + "건)");
        } catch (basicError) {
            console.error("기본 excelDownload도 실패:", basicError);
            dlt_newList.setJSON(originalData);
            $c.win.alert("엑셀 다운로드에 실패했습니다.");
        }
    }
};

/**
 * 프로젝트 변경 시 호출되는 함수 (부모 창에서 호출)
 */
scwin.onProjectChange = function(projectId) {
    console.log("프로젝트 변경 이벤트 수신:", projectId);

    scwin.CURRENT_PROJECT_ID = projectId;
    scwin.getCurrentUserInfo();
    scwin.adjustUIByPermission();

    if (projectId && projectId !== "") {
        scwin.searchDefectsByProject();
        scwin.loadStatisticsByProject();
    } else {
        scwin.searchDefects();
        scwin.loadStatistics();
    }
};

/**
 * 통계 조회
 */
scwin.loadStatistics = function() {
    console.log("통계 조회 시작");
    $c.sbm.execute($p, sbm_selectDefStatistics);
};

/**
 * 프로젝트별 통계 조회
 */
scwin.loadStatisticsByProject = function() {
    if (!scwin.CURRENT_PROJECT_ID || scwin.CURRENT_PROJECT_ID === "") {
        scwin.loadStatistics();
        return;
    }

    console.log("프로젝트별 통계 조회 시작: " + scwin.CURRENT_PROJECT_ID);
    dmp_search.set("pjtId", scwin.CURRENT_PROJECT_ID);
    $c.sbm.execute($p, sbm_selectDefStatisticsByProject);
};

/**
 * 통계 조회 완료
 */
scwin.sbm_selectDefStatistics_submitdone = function(e) {
    console.log("통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    dmp_statistics.setJSON(elData);
};

/**
 * 프로젝트별 통계 조회 완료
 */
scwin.sbm_selectDefStatisticsByProject_submitdone = function(e) {
    console.log("프로젝트별 통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc !== true) {
        console.error("프로젝트별 통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    dmp_statistics.setJSON(elData);
};

/**
 * 엑셀 다운로드용 데이터 조회 완료
 */
scwin.sbm_selectDefListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    if (!elData.defVoList || elData.defVoList.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    var processedData = elData.defVoList.map(function(item) {
        return {
            id: item.id,
            testId: item.testId,
            testName: item.testName,
            name: item.name,
            description: item.description,
            priority: item.priority,
            status: item.status,
            assignee: item.assignee,
            assigneeName: item.assigneeName,
            fixDueDate: item.fixDueDate,
            fixedDate: item.fixedDate,
            responsePlan: item.responsePlan,
            createdAt: item.createdAt,
            updatedAt: item.updatedAt,
            priorityName: scwin.getPriorityName(item.priority),
            statusName: scwin.getStatusName(item.status)
        };
    });

    var originalData = dlt_defVoList.getAllJSON();
    dlt_defVoList.setJSON(processedData);

    var options = {
        fileName: "결함_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1, 
        trim: 1,
        removeColumns: "9,10",
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            $c.win.alert("엑셀 파일 다운로드가 완료되었습니다.");
            dlt_defVoList.setJSON(originalData);
        },
        onFailureCallback: function () {
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            dlt_defVoList.setJSON(originalData);
        }
    };

    new_grd.advancedExcelDownload(options);
};
